// Validate the alert contract BEFORE any external effect.
const b = $json.body || $json;
const SEVERITIES = ['info', 'warning', 'critical'];
const sev = SEVERITIES.includes(String(b.severity || '').toLowerCase())
  ? String(b.severity).toLowerCase() : 'info';
const caseCode = String(b.caseCode || '').trim();
const event = String(b.event || '').trim();
if (!caseCode) {
  throw new Error('caseCode is required');
}
if (!event) {
  throw new Error('event is required');
}
return {
  json: {
    caseCode,
    event,
    titleAr: String(b.titleAr || 'تحديث بشأن القضية').slice(0, 300),
    detailsAr: String(b.detailsAr || '').slice(0, 3000),
    severity: sev,
    occurredAt: new Date().toISOString(),
  }
};

// The scrubber returns { scrubbed_text, ... } overwriting the item;
// re-attach the metadata we validated earlier so later nodes see one item.
const s = $json.scrubbed_text || '';
const prev = $('Validate + Normalize Event').item.json;
const [titleAr = '', ...rest] = s.split('\n');
return { json: {
  caseCode: prev.caseCode,
  event: prev.event,
  severity: prev.severity,
  occurredAt: prev.occurredAt,
  titleAr: titleAr || prev.titleAr,
  detailsAr: rest.join('\n'),
} };

// Assemble the channel message with the MANDATORY disclaimer.
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const item = $json;
const DISCLAIMER =
  '⚠️ <b>إخلاء مسؤولية إلزامي:</b> هذا التنبيه مُولّد آلياً كأداة تنظيمية مساعدة، ' +
  'ولا يُغني بأي حال عن مراجعة ملف القضية أو استشارة محامٍ مقيّد بنقابة المحامين المصريين. ' +
  'المنظومة لا تتحمل مسؤولية أي تصرف بناءً عليها.';
const SEV_ICON = { info: 'ℹ️', warning: '⚠️', critical: '🚨' };
const SEV_TITLE = { info: 'تحديث', warning: 'تنبيه', critical: 'عاجل' };
const sev = ['info', 'warning', 'critical'].includes(item.severity) ? item.severity : 'info';
const lines = [
  SEV_ICON[sev] + ' <b>CRIM-SYS — ' + SEV_TITLE[sev] + ' قضية</b>',
  '',
  '📁 القضية: ' + esc(item.caseCode),
  '🔖 الحدث: ' + esc(item.event),
];
if (item.titleAr) lines.push('📌 ' + esc(item.titleAr));
if (item.detailsAr) lines.push('📝 ' + esc(item.detailsAr));
lines.push('', '🕒 ' + esc(new Date(item.occurredAt).toLocaleString('ar-EG', { timeZone: 'Africa/Cairo' })), '', DISCLAIMER);
return { json: { message: lines.join('\n') } };
